//! Deferred actual canvas wide native target routing; no visual acceptance.
use super::*;
#[path="../../engine/src/accounted_wide_plain_xcf_test_support.rs"]mod f;
fn app(gray:bool,sample:photocraft_color::SampleType)->PhotocraftApp{let input=f::import(gray,sample,false);let mut s=photocraft_engine::Session::new();s.add_owned_plain_xcf_import(&input,"legacy-wide.xcf",Some("authorized/legacy-wide.xcf"),&f::ctl()).unwrap();s.tools.brush.pressure_size=false;s.tools.brush.size=7.0;let mut app=PhotocraftApp::new(s,Default::default());app.ui.tool=Tool::Brush;app}
#[test]
#[ignore="UNRUN/uncompiled actual Legacy U32/F64 RGB/Gray canvas Down/Move/Up captured native COW, no live preview, original precision/history and stale zoom/tool/source refusal. UI swatch remains inherently F32; no visual/oracle claim."]
fn wide_canvas_uses_the_original_native_target(){
 for gray in [false,true]{for sample in [photocraft_color::SampleType::U32,photocraft_color::SampleType::F64]{let mut a=app(gray,sample);let before=a.session.active().unwrap().doc.clone();let raw=f::payload(&before);assert_eq!(raw,f::expected(gray,sample));let rev=a.session.active().unwrap().revision;tool_event(&mut a,ToolEvent::Down{x:253.0,y:254.0,pressure:1.0},egui::Modifiers::NONE);assert!(a.drag.as_ref().unwrap().native_stroke_target.is_some());assert!(a.live_stroke.is_none());tool_event(&mut a,ToolEvent::Move{x:255.0,y:256.0,pressure:0.8},egui::Modifiers::NONE);assert!(before.shares_state(&a.session.active().unwrap().doc));tool_event(&mut a,ToolEvent::Up{x:256.0,y:257.0},egui::Modifiers::NONE);assert!(!a.ui.status_error,"{}",a.ui.status);assert_eq!(a.session.active().unwrap().revision,rev+1);assert_eq!(a.session.active().unwrap().doc.depth,sample);assert_ne!(f::payload(&a.session.active().unwrap().doc),raw);assert_eq!(f::payload(&before),raw);a.session.undo_with_control(&f::ctl()).unwrap();assert_eq!(f::payload(&a.session.active().unwrap().doc),raw);}}
 for variant in 0..3{let mut a=app(false,photocraft_color::SampleType::F64);let before=a.session.active().unwrap().doc.clone();tool_event(&mut a,ToolEvent::Down{x:2.0,y:2.0,pressure:1.0},egui::Modifiers::NONE);let d=a.drag.take().unwrap();match variant{0=>{let index=a.session.active_index().unwrap();a.ui.views.resize_with(index+1,Default::default);a.ui.views[index].zoom=2.0;},1=>a.ui.tool=Tool::Pencil,_=>a.session.active_mut().unwrap().source_read_only=false};assert!(native_stroke::commit(&mut a,&d));assert!(a.ui.status_error);assert!(before.shares_state(&a.session.active().unwrap().doc));}
}
